const JWT = /eyJ[A-Za-z0-9_-]{4,2048}\.[A-Za-z0-9_-]{4,2048}\.[A-Za-z0-9_-]{0,2048}/g;
const EMAIL = /[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9.-]{1,253}\.[A-Za-z]{2,63}/g;
const COORD_PAIR = /-?\d{1,3}\.\d{3,12}[ \t]{0,3}[,;/ ][ \t]{0,3}-?\d{1,3}\.\d{3,12}/g;
const MAX_REDACT_CHARS = 4096;
const TOKEN_CHAR = /[A-Za-z0-9._%+@*-]/;

function truncate(s) {
  if (s.length <= MAX_REDACT_CHARS) return s;
  let end = MAX_REDACT_CHARS;
  while (end > 0 && TOKEN_CHAR.test(s[end - 1])) end--; // never keep a cut token
  return s.slice(0, end) + "[TRUNCATED]";
}

function redactString(s) {
  let out = String(s);
  for (const v of sorted) {
    if (out.includes(v)) out = out.split(v).join(REDACTED);
  }
  return truncate(out)
    .replace(JWT, REDACTED)
    .replace(EMAIL, REDACTED)
    .replace(HEX32, REDACTED)
    .replace(MASKED_ID, REDACTED)
    .replace(VIN_LIKE, REDACTED)
    .replace(COORD_PAIR, REDACTED)
    .replace(COORD_ONE, REDACTED);
}

